    image_patch = ImagePatch(image)
    person_patches = image_patch.find("person")
    if not person_patches:
        return image_patch
    person_patches.sort(key=lambda p: p.horizontal_center)
    for person_patch in person_patches:
        if person_patch.verify_property("person", "yellow"):
            return person_patch
    return person_patches[0]

